#!/usr/bin/env bash
# Download the public NHANES XPT files used by the analysis from the CDC/NCHS website
# (https://wwwn.cdc.gov/nchs/nhanes/). No data are redistributed in this package.
set -u
cd "$(dirname "$0")/data/raw"
declare -A Y=([B]=2001 [C]=2003 [D]=2005 [E]=2007 [F]=2009 [G]=2011 [H]=2013 [I]=2015 [J]=2017 [L]=2021)
FILES="ALB_CR_E ALB_CR_F ALB_CR_G ALB_CR_H ALB_CR_I ALQ_B ALQ_C ALQ_D ALQ_E ALQ_F ALQ_G ALQ_H ALQ_I ALQ_J ALQ_L BIOPRO_E BIOPRO_F BIOPRO_G BIOPRO_H BIOPRO_I BMX_E BMX_F BMX_G BMX_H BMX_I BPQ_B BPQ_C BPQ_D BPQ_E BPQ_F BPQ_G BPQ_H BPQ_I BPQ_J BPQ_L BPX_E BPX_F BPX_G BPX_H BPX_I CBC_E CBC_F CBC_G CBC_H CBC_I COT_H COT_I CRP_E CRP_F DEMO_B DEMO_C DEMO_D DEMO_E DEMO_F DEMO_G DEMO_H DEMO_I DEMO_J DEMO_L DIQ_E DIQ_F DIQ_G DIQ_H DIQ_I DPQ_E DPQ_F DPQ_G DPQ_H DPQ_I DR1TOT_C DR1TOT_D DR1TOT_E DR1TOT_F DR1TOT_G DR1TOT_H DR1TOT_I DR1TOT_J DR1TOT_L DSQTOT_E DSQTOT_F DSQTOT_G DSQTOT_H DSQTOT_I EPHPP_H EPHPP_I EPHPP_J EPH_E EPH_F EPH_G FERTIN_E FERTIN_F FERTIN_I FOLATE_E FOLATE_F FOLATE_G FOLATE_H FOLATE_I FOLFMS_E FOLFMS_G FOLFMS_H FOLFMS_I GHB_E GHB_F GHB_G GHB_H GHB_I GLU_E GLU_F GLU_G GLU_H GLU_I HDL_E HDL_F HDL_G HDL_H HDL_I HIQ_E HIQ_F HIQ_G HIQ_H HIQ_I HOQ_E HOQ_F HOQ_G HOQ_H HOQ_I HSCRP_I INS_H INS_I MCQ_B MCQ_C MCQ_D MCQ_E MCQ_F MCQ_G MCQ_H MCQ_I MCQ_J MCQ_L OCQ_E OCQ_F OCQ_G OCQ_H OCQ_I PAQ_B PAQ_C PAQ_D PAQ_E PAQ_F PAQ_G PAQ_H PAQ_I PAQ_J PAQ_L PBCD_E PBCD_F PBCD_G PBCD_H PBCD_I PERNTS_G PERNTS_H PERNTS_I PHTHTE_E PHTHTE_F PHTHTE_G PHTHTE_H PHTHTE_I PHTHTE_J PSTPOL_E PSTPOL_F PSTPOL_G PSTPOL_H PSTPOL_I P_ALB_CR P_ALQ P_BIOPRO P_BMX P_BPQ P_BPXO P_CBC P_COT P_DEMO P_DIQ P_DPQ P_DR1TOT P_DSQTOT P_FERTIN P_FETIB P_FOLATE P_FOLFMS P_GHB P_GLU P_HDL P_HIQ P_HSCRP P_INS P_MCQ P_OCQ P_PAQ P_PBCD P_RHQ P_RXQ_RX P_SLQ P_SMQ P_TCHOL P_TFR P_TRIGLY P_UHG P_UIO RHQ_B RHQ_C RHQ_D RHQ_E RHQ_F RHQ_G RHQ_H RHQ_I RHQ_J RHQ_L RXQ_RX_C RXQ_RX_E RXQ_RX_F RXQ_RX_G RXQ_RX_H RXQ_RX_I RXQ_RX_J SLQ_E SLQ_F SLQ_G SLQ_H SLQ_I SMQ_E SMQ_F SMQ_G SMQ_H SMQ_I SMQ_J TCHOL_E TCHOL_F TCHOL_G TCHOL_H TCHOL_I TFR_E TFR_F TFR_I THYROD_E THYROD_F THYROD_G TRIGLY_E TRIGLY_F TRIGLY_G TRIGLY_H TRIGLY_I UHG_E UHG_F UHG_G UHG_H UHG_I UIO_E UIO_F UIO_G UIO_H UIO_I VID_E VID_F VID_G VID_H VID_I VID_J VITB12_G VITB12_H "
log=../download_log.tsv; : > "$log"; fail=0
for n in $FILES; do
  if [[ $n == P_* ]]; then yr=2017; else yr=${Y[${n##*_}]}; fi
  if [ ! -s "$n.xpt" ]; then
    curl -sSfL --retry 3 -o "$n.xpt" "https://wwwn.cdc.gov/Nchs/Data/Nhanes/Public/$yr/DataFiles/$n.xpt" || true
  fi
  if [ -s "$n.xpt" ] && ! head -c 200 "$n.xpt" | grep -qi "<html\|<!DOCTYPE"; then
    printf '%s\t%s\tok\n' "$n" "$yr" >> "$log"
  else rm -f "$n.xpt"; printf '%s\t%s\tNOT_FOUND\n' "$n" "$yr" >> "$log"; fail=1; fi
done
echo "files: $(grep -c ok "$log") ok; missing: $(grep -c NOT_FOUND "$log")"
exit $fail
